import re,glob,os
files=sorted(glob.glob('draft/*.md'))+sorted(glob.glob('figures/*.md'))
table=set()
for line in open('draft/numerals.md'):
    m=re.match(r'\|\s*(\d+)\s*\|\s*(.+?)\s*\|',line)
    if m and m.group(1).isdigit(): table.add(int(m.group(1)))
print('table',sorted(table))
used={}
for f in files:
    t=open(f).read()
    if f.endswith('numerals.md'): continue
    ns=set(int(x) for x in re.findall(r'(?<![\d.])\b(\d{2})\b(?!\.)',t))
    used[f]=ns
allused=set()
for f,ns in used.items():
    extra=ns-table
    print(f, sorted(ns), 'NOT-IN-TABLE:',sorted(extra) if extra else '')
    allused|=ns&table
print('table numerals never used:',sorted(table-allused))
# markers
bad=re.compile(r'(TODO|TBD|\[\s*\]|XXX|placeholder|draftsperson|FIXME|<insert|\bNote to\b|\?\?)',re.I)
for f in files:
    for i,l in enumerate(open(f),1):
        if bad.search(l): print('MARKER',f,i,l.strip()[:120])
        if '—' in l or '–' in l: print('DASH',f,i,l.strip()[:120])
